const {spawn}=require('node:child_process');
const {mkdtempSync,rmSync}=require('node:fs');
const {tmpdir}=require('node:os');
exports.session=async function(){
 const dir=mkdtempSync(tmpdir()+'/proof-case-');
 const child=spawn(process.execPath,['server.js'],{env:{...process.env,PORT:'0',DATA_FILE:dir+'/data.json'},stdio:['ignore','pipe','inherit']});
 let timer;
 try {
  const port=await new Promise((resolve,reject)=>{
   timer=setTimeout(()=>reject(Error('startup timeout')),5000);
   child.once('error',reject);
   let out='';child.stdout.on('data',chunk=>{out+=chunk;const m=out.match(/LISTENING_ON_PORT=(\d+)/);if(m)resolve(m[1]);});
  });
  clearTimeout(timer);
  return {
   async post(path,body,date='2026-01-01'){
    const r=await fetch('http://127.0.0.1:'+port+path,{method:'POST',headers:{'content-type':'application/json','X-Today':date},body:body===undefined?undefined:JSON.stringify(body)});
    return {status:r.status,body:await r.json()};
   },
   async close(){child.kill();await new Promise(resolve=>child.once('close',resolve));rmSync(dir,{recursive:true,force:true});}
  };
 }catch(error){clearTimeout(timer);child.kill();rmSync(dir,{recursive:true,force:true});throw error;}
};

