'use strict';
const http=require('node:http'),fs=require('node:fs'),path=require('node:path');
const DATA=process.env.DATA_FILE||path.join('data','library.json');
const seed={books:[{id:'b1',title:'The City & the Stars',author:'Arthur C. Clarke',copies:2},{id:'b2',title:'Kindred',author:'Octavia E. Butler',copies:1},{id:'b3',title:'The Left Hand of Darkness',author:'Ursula K. Le Guin',copies:1},{id:'b4',title:'The Hobbit',author:'J.R.R. Tolkien',copies:2},{id:'b5',title:'Beloved',author:'Toni Morrison',copies:1},{id:'b6',title:'A Wizard of Earthsea',author:'Ursula K. Le Guin',copies:1}],members:[{id:'m1',name:'Alex Rivera',type:'standard'},{id:'m2',name:'Sam Patel',type:'standard'},{id:'m3',name:'Jordan Lee',type:'premium'}],loans:[],holds:[],payments:[],nextId:1};
let db;function load(){try{db=JSON.parse(fs.readFileSync(DATA,'utf8'))}catch{db=structuredClone(seed);persist()}}function persist(){fs.mkdirSync(path.dirname(DATA),{recursive:true});let t=DATA+'.tmp';fs.writeFileSync(t,JSON.stringify(db,null,2));fs.renameSync(t,DATA)}
function today(q){let x=q.headers['x-today']||new Date().toISOString().slice(0,10);if(!/^\d{4}-\d{2}-\d{2}$/.test(x))return null;let [y,m,d]=x.split('-').map(Number),dt=new Date(Date.UTC(y,m-1,d));return dt.getUTCFullYear()===y&&dt.getUTCMonth()===m-1&&dt.getUTCDate()===d?x:null}function add(s,n){let d=new Date(s+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)}function available(b){return b.copies-db.loans.filter(x=>x.bookId===b.id&&!x.returned).length}function json(r,s,x){let b=JSON.stringify(x);r.writeHead(s,{'content-type':'application/json','content-length':Buffer.byteLength(b)});r.end(b)}function bad(r,m,s=400){json(r,s,{error:m})}function parse(q){return new Promise((ok,no)=>{let s='';q.on('data',c=>s+=c);q.on('end',()=>{try{ok(JSON.parse(s))}catch{no()}})})}function fine(m){return Math.max(0,db.loans.filter(x=>x.memberId===m.id).reduce((a,x)=>a+(x.fineCents||0),0)-db.payments.filter(x=>x.memberId===m.id).reduce((a,x)=>a+x.amountCents,0))}
function view(m){return {id:m.id,name:m.name,type:m.type,activeLoans:db.loans.filter(x=>x.memberId===m.id&&!x.returned),holds:db.holds.filter(x=>x.memberId===m.id),finesOwedCents:fine(m)}}
async function app(q,r){let d=today(q),u=new URL(q.url,'http://x'),p=u.pathname;if(!d)return bad(r,'invalid X-Today');if(q.method==='GET'&&p==='/api/books')return json(r,200,db.books.map(b=>({...b,availableCopies:available(b)})));if(q.method==='GET'&&p==='/api/members')return json(r,200,db.members.map(m=>({...m,finesOwedCents:fine(m)})));let mi=p.match(/^\/api\/members\/([^/]+)$/);if(q.method==='GET'&&mi){let m=db.members.find(x=>x.id===mi[1]);return m?json(r,200,view(m)):bad(r,'member not found',404)}
if(q.method==='POST'&&p==='/api/loans'){let x;try{x=await parse(q)}catch{return bad(r,'malformed body')}if(!x||typeof x.bookId!=='string'||!x.bookId.trim()||typeof x.memberId!=='string'||!x.memberId.trim())return bad(r,'bookId and memberId required');let b=db.books.find(book=>book.id===x.bookId),m=db.members.find(member=>member.id===x.memberId);if(!b||!m)return bad(r,'book or member not found',404);if(db.loans.filter(x=>x.memberId===m.id&&!x.returned).length>=(m.type==='premium'?5:3)||fine(m)>500)return bad(r,'loan refused',409);let hs=db.holds.filter(x=>x.bookId===b.id).sort((a,z)=>a.created.localeCompare(z.created)),h=hs[0];if(available(b)<=0||h&&h.memberId!==m.id)return bad(r,'copy unavailable or reserved',409);let l={id:'l'+db.nextId++,bookId:b.id,memberId:m.id,startDate:d,dueDate:add(d,14),returned:false,renewals:0,fineCents:0};db.loans.push(l);if(h&&h.memberId===m.id)db.holds=db.holds.filter(x=>x.id!==h.id);persist();return json(r,201,l)}
let lm=p.match(/^\/api\/loans\/([^/]+)\/(return|renew)$/);if(q.method==='POST'&&lm){let l=db.loans.find(x=>x.id===lm[1]);if(!l)return bad(r,'loan not found',404);if(l.returned)return bad(r,'loan already returned',409);if(lm[2]==='return'){l.returned=true;l.returnDate=d;l.fineCents=Math.min(1000,Math.max(0,Math.floor((Date.parse(d)-Date.parse(l.dueDate))/86400000))*25);persist();return json(r,200,l)}if(l.renewals>=2||db.holds.some(x=>x.bookId===l.bookId&&x.memberId!==l.memberId))return bad(r,'renewal refused',409);l.dueDate=add(l.dueDate,14);l.renewals++;persist();return json(r,200,l)}
if(q.method==='POST'&&p==='/api/holds'){let x;try{x=await parse(q)}catch{return bad(r,'malformed body')}if(!x||typeof x.bookId!=='string'||typeof x.memberId!=='string'||!x.bookId.trim()||!x.memberId.trim())return bad(r,'bookId and memberId required');let b=db.books.find(book=>book.id===x.bookId),m=db.members.find(member=>member.id===x.memberId);if(!b||!m)return bad(r,'book or member not found',404);if(available(b)>0)return bad(r,'copy available',409);let h={id:'h'+db.nextId++,bookId:b.id,memberId:m.id,created:d};db.holds.push(h);persist();return json(r,201,h)}
let pm=p.match(/^\/api\/members\/([^/]+)\/payments$/);if(q.method==='POST'&&pm){let m=db.members.find(x=>x.id===pm[1]);if(!m)return bad(r,'member not found',404);let x;try{x=await parse(q)}catch{return bad(r,'malformed body')}if(!x||typeof x.amount!=='number'||!Number.isFinite(x.amount)||x.amount<=0||!/^\d+(?:\.\d{1,2})?$/.test(String(x.amount)))return bad(r,'invalid amount');let z={id:'p'+db.nextId++,memberId:m.id,amountCents:Math.round(x.amount*100),date:d};db.payments.push(z);persist();return json(r,201,z)}
if(!p.startsWith('/api/')){let f=p==='/'?'index.html':p.slice(1),file=path.join('public',f);try{if(!fs.existsSync(file)||!fs.statSync(file).isFile())return r.writeHead(404).end();let t={'.html':'text/html','.js':'text/javascript','.css':'text/css'}[path.extname(f)]||'application/octet-stream';r.writeHead(200,{'content-type':t});return fs.createReadStream(file).on('error',()=>{if(!r.headersSent)r.writeHead(404);r.end()}).pipe(r)}catch{return r.writeHead(404).end()}}bad(r,'not found',404)}
load();let s=http.createServer((q,r)=>app(q,r).catch(()=>bad(r,'server error',500)));s.listen(process.env.PORT===undefined?3000:Number(process.env.PORT),()=>console.log('LISTENING_ON_PORT='+s.address().port));

