'use strict';

const $ = (selector) => document.querySelector(selector);
let memberId = '';
let books = [];
let actionQueue = Promise.resolve();

async function request(url, options = {}) {
  const method = options.method || 'GET';
  const body = options.body || null;
  const headers = { 'content-type': 'application/json', ...(options.headers || {}) };
  const result = await new Promise((resolve, reject) => {
    const xhr = new XMLHttpRequest();
    xhr.open(method, url);
    Object.entries(headers).forEach(([name, value]) => xhr.setRequestHeader(name, value));
    xhr.onload = () => resolve({ status: xhr.status, text: xhr.responseText });
    xhr.onerror = () => reject(new Error('Network request failed'));
    xhr.send(body);
  });
  let data;
  try { data = JSON.parse(result.text); } catch { throw new Error(`Request failed (${result.status})`); }
  if (result.status < 200 || result.status >= 300) throw new Error(data.error || `Request failed (${result.status})`);
  return data;
}

function showMessage(text, kind = '') {
  const region = $('#message');
  region.textContent = text;
  region.className = `message ${kind}`;
}

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]));
}

function bookName(id) {
  const book = books.find((item) => item.id === id);
  return book ? book.title : id;
}

function renderBooks() {
  $('#books').innerHTML = books.map((book) => `
    <tr>
      <th scope="row">${escapeHtml(book.title)}</th>
      <td>${escapeHtml(book.author)}</td>
      <td>${book.availableCopies} of ${book.copies}</td>
      <td class="actions">
        <button class="borrow" data-book="${book.id}" type="button" aria-label="Borrow ${escapeHtml(book.title)}">Borrow</button>
        <button class="hold" data-book="${book.id}" type="button" aria-label="Place a hold on ${escapeHtml(book.title)}">Place hold</button>
      </td>
    </tr>`).join('');
}

function renderMember(member) {
  const loans = member.activeLoans.map((loan) => `
    <li>
      <span>${escapeHtml(bookName(loan.bookId))} — due <strong class="due-date">${loan.dueDate}</strong></span>
      <span class="actions">
        <button class="return" data-loan="${loan.id}" type="button">Return</button>
        <button class="renew" data-loan="${loan.id}" type="button">Renew</button>
      </span>
    </li>`).join('');
  const holds = member.holds.length
    ? member.holds.map((hold) => `<li>${escapeHtml(bookName(hold.bookId))}</li>`).join('')
    : '<li>None</li>';
  $('#memberView').innerHTML = `
    <p class="fine">Fines owed: <strong>$${(member.finesOwedCents / 100).toFixed(2)}</strong></p>
    <h3>Active loans</h3>
    <ul class="loan-list">${loans || '<li>None</li>'}</ul>
    <h3>Holds</h3>
    <ul class="hold-list">${holds}</ul>`;
}

async function refresh() {
  books = await request('/api/books');
  renderBooks();
  renderMember(await request(`/api/members/${encodeURIComponent(memberId)}`));
}

function action(url, options) {
  actionQueue = actionQueue.then(async () => {
    try {
      await request(url, options);
      showMessage('Action completed.', 'success');
      await refresh();
    } catch (error) {
      showMessage(error.message, 'error');
    }
  });
  return actionQueue;
}

document.addEventListener('click', (event) => {
  const button = event.target.closest('button');
  if (!button) return;
  const body = JSON.stringify({ bookId: button.dataset.book, memberId });
  if (button.classList.contains('borrow')) return action('/api/loans', { method: 'POST', body });
  if (button.classList.contains('hold')) return action('/api/holds', { method: 'POST', body });
  if (button.classList.contains('return')) return action(`/api/loans/${button.dataset.loan}/return`, { method: 'POST' });
  if (button.classList.contains('renew')) return action(`/api/loans/${button.dataset.loan}/renew`, { method: 'POST' });
});

$('#member').addEventListener('change', async (event) => {
  memberId = event.target.value;
  try { await refresh(); } catch (error) { showMessage(error.message, 'error'); }
});

async function init() {
  const members = await request('/api/members');
  $('#member').innerHTML = members.map((member) => `<option value="${member.id}">${escapeHtml(member.name)} (${member.type})</option>`).join('');
  memberId = $('#member').value;
  await refresh();
}

init().catch((error) => showMessage(error.message, 'error'));
